119	final class GraphBuilder {
120	    private final List<List<Edge>> adjacency;
121	
122	    private GraphBuilder(List<List<Edge>> adjacency) {
123	        this.adjacency = adjacency;
124	    }
125	
126	    static GraphBuilder withVertexCount(int vertexCount) {
127	        GraphChecks.validateVertexCount(vertexCount);
128	
129	        List<List<Edge>> adjacency = new ArrayList<>(vertexCount);
130	        for (int vertex = 0; vertex < vertexCount; vertex++) {
131	            adjacency.add(new ArrayList<>());
132	        }
133	        return new GraphBuilder(adjacency);
134	    }
135	
136	    GraphBuilder addUndirectedConnection(Connection connection) {
137	        validateConnection(connection);
138	        addDirectedEdgeUnchecked(connection.from, connection.to, connection.weight);
139	        addDirectedEdgeUnchecked(connection.to, connection.from, connection.weight);
140	        return this;
141	    }
142	
143	    GraphBuilder addDirectedConnection(Connection connection) {
144	        validateConnection(connection);
145	        addDirectedEdgeUnchecked(connection.from, connection.to, connection.weight);
146	        return this;
147	    }
148	
149	    Graph build() {
150	        return Graph.fromMutableAdjacency(adjacency);
151	    }
152	
153	    private void addDirectedEdgeUnchecked(int from, int to, int weight) {
154	        adjacency.get(from).add(new Edge(to, weight));
155	    }
156	
157	    private void validateConnection(Connection connection) {
158	        if (connection == null) {
159	            throw new IllegalArgumentException("Connection must not be null");
160	        }
161	
162	        GraphChecks.validateVertex(connection.from, adjacency.size(), "from");
163	        GraphChecks.validateVertex(connection.to, adjacency.size(), "to");
164	        GraphChecks.validateWeight(connection.weight);
165	    }
