173	        GraphBuilder graph = GraphBuilder.withVertexCount(legacyGraph.vertexCount());
174	        for (int from = 0; from < legacyGraph.vertexCount(); from++) {
175	            for (Connection connection : legacyGraph.connectionsFrom(from)) {
