183	final class LegacyGraph {
184	    private static final int DESTINATION_INDEX = 0;
185	    private static final int WEIGHT_INDEX = 1;
186	    private static final int EDGE_FIELD_COUNT = 2;
187	
188	    private final ArrayList<ArrayList<int[]>> adjacency;
189	
190	    private LegacyGraph(ArrayList<ArrayList<int[]>> adjacency) {
191	        this.adjacency = adjacency;
192	    }
193	
194	    static LegacyGraph fromAdjacencyList(ArrayList<ArrayList<int[]>> adjacency) {
195	        validateAdjacencyList(adjacency);
196	        return new LegacyGraph(adjacency);
197	    }
198	
199	    int vertexCount() {
200	        return adjacency.size();
201	    }
202	
203	    void addUndirectedEdge(int u, int v, int weight) {
204	        GraphChecks.validateVertex(u, vertexCount(), "u");
205	        GraphChecks.validateVertex(v, vertexCount(), "v");
206	        GraphChecks.validateWeight(weight);
207	
208	        adjacency.get(u).add(edge(v, weight));
209	        adjacency.get(v).add(edge(u, weight));
210	    }
211	
212	    List<Connection> connectionsFrom(int from) {
213	        GraphChecks.validateVertex(from, vertexCount(), "from");
214	
215	        ArrayList<int[]> rawEdges = requireNeighborList(from);
216	        ArrayList<Connection> connections = new ArrayList<>(rawEdges.size());
217	        for (int[] rawEdge : rawEdges) {
218	            connections.add(toConnection(from, rawEdge));
219	        }
220	        return connections;
221	    }
222	
223	    private Connection toConnection(int from, int[] rawEdge) {
224	        validateRawEdge(rawEdge, from);
225	
226	        int to = rawEdge[DESTINATION_INDEX];
227	        int weight = rawEdge[WEIGHT_INDEX];
228	        GraphChecks.validateVertex(to, vertexCount(), "neighbor");
229	        GraphChecks.validateWeight(weight);
230	        return Connection.of(from, to, weight);
231	    }
232	
233	    private ArrayList<int[]> requireNeighborList(int vertex) {
234	        ArrayList<int[]> neighbors = adjacency.get(vertex);
235	        if (neighbors == null) {
236	            throw new IllegalArgumentException(
237	                    "Adjacency list contains a null neighbor list at vertex " + vertex);
238	        }
239	        return neighbors;
240	    }
241	
242	    private static int[] edge(int destination, int weight) {
243	        return new int[]{destination, weight};
244	    }
245	
246	    private static void validateAdjacencyList(ArrayList<ArrayList<int[]>> adjacency) {
247	        if (adjacency == null) {
248	            throw new IllegalArgumentException("Adjacency list must not be null");
249	        }
250	    }
251	
252	    private static void validateRawEdge(int[] rawEdge, int fromVertex) {
253	        if (rawEdge == null || rawEdge.length < EDGE_FIELD_COUNT) {
254	            throw new IllegalArgumentException(
255	                    "Edge at vertex " + fromVertex + " must contain destination and weight");
256	        }
257	    }
258	}
