270	final class Distances {
271	    private static final int UNREACHABLE = Integer.MAX_VALUE;
272	
273	    private final int[] values;
274	
275	    private Distances(int[] values) {
276	        this.values = values;
277	    }
278	
279	    static Distances forSource(int vertexCount, int source) {
280	        int[] values = new int[vertexCount];
281	        Arrays.fill(values, UNREACHABLE);
282	        values[source] = 0;
283	        return new Distances(values);
284	    }
285	
286	    boolean isStale(QueueEntry entry) {
287	        return entry.distance != values[entry.vertex];
288	    }
289	
290	    boolean tryUpdate(int vertex, int nextDistance) {
291	        if (nextDistance >= values[vertex]) {
292	            return false;
293	        }
294	
295	        values[vertex] = nextDistance;
296	        return true;
297	    }
298	
299	    ArrayList<Integer> toList() {
300	        ArrayList<Integer> result = new ArrayList<>(values.length);
301	        for (int distance : values) {
302	            result.add(distance);
303	        }
304	        return result;
305	    }
306	}
