308	final class ShortestPathSolver {
309	    private final Graph graph;
310	    private final Distances distances;
311	    private final PriorityQueue<QueueEntry> minHeap;
312	
313	    private ShortestPathSolver(Graph graph, int source) {
314	        this.graph = graph;
315	        this.distances = Distances.forSource(graph.vertexCount(), source);
316	        this.minHeap = new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
317	        minHeap.offer(new QueueEntry(0, source));
318	    }
319	
320	    static Distances solve(Graph graph, int source) {
321	        return new ShortestPathSolver(graph, source).run();
322	    }
323	
324	    private Distances run() {
325	        while (!minHeap.isEmpty()) {
326	            QueueEntry current = minHeap.poll();
327	            if (distances.isStale(current)) {
328	                continue;
329	            }
330	
331	            relaxNeighborsOf(current);
332	        }
333	        return distances;
334	    }
335	
336	    private void relaxNeighborsOf(QueueEntry current) {
337	        for (Edge edge : graph.neighborsOf(current.vertex)) {
338	            tryRelax(current, edge);
339	        }
340	    }
341	
342	    private void tryRelax(QueueEntry current, Edge edge) {
343	        int nextDistance = GraphChecks.addDistances(current.distance, edge.weight);
344	        if (distances.tryUpdate(edge.to, nextDistance)) {
345	            minHeap.offer(new QueueEntry(nextDistance, edge.to));
346	        }
347	    }
348	}
